<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\GalleryItem;use App\Models\GalleryCategory;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\View\View;use Illuminate\Http\RedirectResponse;
class GalleryAdminController extends Controller {public function index():View{return view('admin.gallery.index',['items'=>GalleryItem::with('galleryCategory')->orderBy('sort_order')->latest()->paginate(20),'categories'=>GalleryCategory::orderBy('sort_order')->orderBy('name')->get()]);}public function store(Request $r):RedirectResponse{$v=$r->validate(['title'=>'required|string|max:150','category'=>'nullable|string|max:100','gallery_category_id'=>'nullable|exists:gallery_categories,id','alt_text'=>'nullable|string|max:250','image'=>'required|image|max:5120','is_published'=>'nullable|boolean']);$category = !empty($v['gallery_category_id']) ? GalleryCategory::find($v['gallery_category_id']) : null; $v['category'] = $category?->name ?? ($v['category'] ?? 'Coiffure'); $v['image_path']=$r->file('image')->store('gallery','public');unset($v['image']);$v['is_published']=(bool)($v['is_published']??false);GalleryItem::create($v);return back()->with('success','Photo ajoutée à la galerie.');}public function toggle(GalleryItem $item):RedirectResponse{$item->update(['is_published'=>!$item->is_published]);return back()->with('success','Visibilité mise à jour.');}public function destroy(GalleryItem $item):RedirectResponse{Storage::disk('public')->delete($item->image_path);$item->delete();return back()->with('success','Photo supprimée.');}}
